import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Store references for cleanup
  const timelines = [];
  const cleanupFns = [];
  let gltfScene = null;

  // Load the gear mesh asynchronously but return the group immediately
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    try {
      // Clone the loaded scene to avoid shared state
      gltfScene = gltf.scene.clone();
      group.add(gltfScene);

      // Traverse mesh and upgrade materials to NodeMaterial for edge lighting
      gltfScene.traverse((node) => {
        if (node.isMesh && node.material) {
          const originalMaterial = node.material;

          // Create NodeMaterial version with edge rim light enhancement
          const nodeMat = new MeshStandardNodeMaterial({
            color: originalMaterial.color || 0xffffff,
            metalness: Math.min(originalMaterial.metalness || 0.5, 0.55),
            roughness: Math.max(originalMaterial.roughness || 0.5, 0.5),
            clearcoat: Math.min(originalMaterial.clearcoat || 0, 0.25),
          });

          // If original has a map, copy it
          if (originalMaterial.map) {
            nodeMat.map = originalMaterial.map;
          }

          // Add rim light via emissive boost on edges
          nodeMat.emissiveIntensity = 0.4;
          if (!nodeMat.emissive || nodeMat.emissive.getHex() === 0x000000) {
            nodeMat.emissive = new THREE.Color(config.intent?.visualSpec?.colors?.accent || '#ff2a38');
          }

          node.material = nodeMat;
          node.material.needsUpdate = true;
        }
      });

      // Apply cinematic primitives from config after mesh loads
      if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
          if (!prim.name || !ctx.primitives[prim.name]) continue;

          const result = ctx.primitives[prim.name](group, prim.params || {});
          if (result?.cleanup) cleanupFns.push(result.cleanup);
          if (result?.timeline) timelines.push(result.timeline);
        }
      }
    } catch (err) {
      console.error('Failed to process mesh:', err);
    }
  }).catch((err) => {
    console.error('Failed to load mesh:', err);
  });

  // Apply scene position from config
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  }

  // Hover interaction: rise-in subtle entrance (0.15 units)
  let hoverTimeline = null;
  const onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.6,
      ease: 'power3.out',
    });
    timelines.push(hoverTimeline);
  };

  const onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: config.scenePosition?.y ?? 0,
      duration: 0.8,
      ease: 'power4.out',
      overwrite: 'auto',
    });
    timelines.push(hoverTimeline);
  };

  // Click interaction: emit navigation event
  const onClick = () => {
    ctx.emit('navigate', { to: 'hub-journal' });
  };

  // Attach handlers
  group.userData.handlers = {
    hover: onHover,
    hoverOut: onHoverOut,
    click: onClick,
  };

  // Cleanup function
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl?.kill());
    cleanupFns.forEach((fn) => fn?.());
    group.traverse((node) => {
      if (node.geometry) node.geometry.dispose();
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach((m) => m.dispose());
        } else {
          node.material.dispose();
        }
      }
    });
  };

  return group;
}
